<?php if ($actor['role']==='official'): $duplicateSuggestions=br_store()->possibleDuplicates($actor['id'],$c['id']); ?>
<?php if ($duplicateSuggestions): ?><section class="case-section"><h3 class="section-title">Possible Existing Concern</h3><p class="form-text">Review these suggestions. Reports remain separate until you decide to link them. Up to ten strongest matches are shown from the 100 nearest recent or open candidates.</p>
<?php foreach($duplicateSuggestions as $candidate): ?><article class="weekly-concern"><strong><?= h($candidate['id']) ?></strong><ul><?php foreach($candidate['reasons'] as $reason): ?><li><?= h($reason) ?></li><?php endforeach ?></ul><p class="form-text">Reported <?= (int)$candidate['daysAgo'] ?> day(s) ago · <?= h(br_status_label($candidate['status'])) ?></p>
<div class="d-flex flex-wrap gap-2"><a class="btn btn-light btn-sm" href="<?= h(br_url('concern.php',['id'=>$candidate['id']])) ?>">View Concern</a><form method="post" action="api.php" data-action="link_concern" data-id="<?= h($c['id']) ?>"><input type="hidden" name="primaryConcernId" value="<?= h($candidate['id']) ?>"><button type="submit" class="btn btn-light btn-sm">Link as Related/Duplicate</button></form><form method="post" action="api.php" data-action="dismiss_duplicate" data-id="<?= h($c['id']) ?>"><input type="hidden" name="candidateId" value="<?= h($candidate['id']) ?>"><button type="submit" class="btn btn-light btn-sm">Keep Separate</button></form></div></article><?php endforeach ?>
</section><?php endif; endif ?>
